    for role,n in [('strength_match',1000),('audit',2000)]:
        order=np.empty((n,15,5),np.int8)
        for i in range(n):
            for op in range(15):
                order[i,op,:4]=rng.choice(np.delete(np.arange(15),op),4,replace=False);order[i,op,4]=op
